from datetime import date, timedelta

class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine
        self.books = {}  # book_id -> {'borrowed_by': user, 'borrow_date': date} or None if available
        self.fines = {}  # user -> float (unpaid fines)
        self.borrow_history = {}  # user -> list of (book_id, borrow_date, return_date, fine)

    def add_book(self, book_id: str) -> None:
        self.books[book_id] = None

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self.books:
            raise ValueError(f"Book {book_id} does not exist")

        if self.books[book_id] is not None:
            raise ValueError(f"Book {book_id} is already borrowed")

        # Check if user has unpaid fines and already has a borrowed book
        if user in self.fines and self.fines[user] > 0:
            # Count how many books this user currently has borrowed
            borrowed_count = 0
            for book_info in self.books.values():
                if book_info is not None and book_info['borrowed_by'] == user:
                    borrowed_count += 1
            if borrowed_count >= 1:
                raise ValueError(f"User {user} already has a borrowed book")

        self.books[book_id] = {'borrowed_by': user, 'borrow_date': day}

        # Initialize user's fine record if not exists
        if user not in self.fines:
            self.fines[user] = 0.0

    def return_book(self, user: str, book_id: str, day: date) -> float:
        if book_id not in self.books:
            raise ValueError(f"Book {book_id} does not exist")

        book_info = self.books[book_id]
        if book_info is None:
            raise ValueError(f"Book {book_id} is not currently borrowed")

        if book_info['borrowed_by'] != user:
            raise ValueError(f"Book {book_id} was not borrowed by user {user}")

        # Calculate fine
        borrow_date = book_info['borrow_date']
        due_date = borrow_date + timedelta(days=self.loan_days)

        # Count business days (Mon-Fri) of delay
        fine_days = 0
        current_date = due_date + timedelta(days=1)
        while current_date <= day:
            # Only count Monday-Friday (0-4)
            if current_date.weekday() < 5:
                fine_days += 1
            current_date += timedelta(days=1)

        fine_amount = fine_days * self.daily_fine

        # Update user's fine
        if user not in self.fines:
            self.fines[user] = 0.0
        self.fines[user] += fine_amount

        # Mark book as returned
        self.books[book_id] = None

        # Store in history
        if user not in self.borrow_history:
            self.borrow_history[user] = []
        self.borrow_history[user].append((book_id, borrow_date, day, fine_amount))

        return fine_amount

    def unpaid_fines(self, user: str) -> float:
        return self.fines.get(user, 0.0)

    def pay(self, user: str) -> None:
        if user in self.fines:
            self.fines[user] = 0.0
